/**
 * Function call and data source mapping for expression translation.
 *
 * Maps AWS-specific data source references to provider-specific variables,
 * and flags unknown custom functions with informational findings.
 *
 * @module expressions/function-mapper
 * @generated by code-generator (TASK-TRANS-009)
 */

import type { TranslationFinding } from '@tla/shared';
import type { ExpressionContext, TranslatedExpression } from './types.js';
import { createFinding } from '../engines/direct/attribute-transformer.js';

// ---------------------------------------------------------------------------
// Data source mapping
// ---------------------------------------------------------------------------

/**
 * Map of AWS data source reference patterns to provider-specific replacements.
 * Keys are reference prefixes; values are { azure, gcp } replacement strings.
 */
const DATA_SOURCE_MAP: ReadonlyMap<
  string,
  Readonly<{ azure: string; gcp: string }>
> = new Map([
  [
    'data.aws_caller_identity.current.account_id',
    { azure: 'var.subscription_id', gcp: 'var.project_id' },
  ],
  [
    'data.aws_caller_identity.current.arn',
    { azure: 'var.tenant_id', gcp: 'var.project_id' },
  ],
  [
    'data.aws_region.current.name',
    { azure: 'var.location', gcp: 'var.region' },
  ],
  [
    'data.aws_partition.current.partition',
    { azure: '"azure"', gcp: '"gcp"' },
  ],
]);

/**
 * Prefix-based data source mappings for references that vary by name.
 * Matched when the full reference does not appear in DATA_SOURCE_MAP.
 */
const DATA_SOURCE_PREFIX_MAP: ReadonlyArray<
  Readonly<{
    prefix: string;
    azure: string;
    gcp: string;
  }>
> = [
  {
    prefix: 'data.aws_ami.',
    azure: 'var.vm_image_id',
    gcp: 'var.machine_image',
  },
  {
    prefix: 'data.aws_availability_zones.',
    azure: 'var.availability_zones',
    gcp: 'var.zones',
  },
];

/**
 * Attempts to map an AWS data source reference to a provider-specific replacement.
 *
 * @param ref - The full data source reference (e.g. "data.aws_caller_identity.current.account_id")
 * @param ctx - Expression translation context
 * @returns A TranslatedExpression if the ref is a known data source, or null
 */
export function mapDataSource(
  ref: string,
  ctx: ExpressionContext,
): TranslatedExpression | null {
  if (!ref.startsWith('data.')) {
    return null;
  }

  // Exact match first
  const exact = DATA_SOURCE_MAP.get(ref);
  if (exact) {
    const replacement = ctx.target === 'azure' ? exact.azure : exact.gcp;
    return { rewritten: replacement, findings: [] };
  }

  // Prefix match
  for (const entry of DATA_SOURCE_PREFIX_MAP) {
    if (ref.startsWith(entry.prefix)) {
      const replacement = ctx.target === 'azure' ? entry.azure : entry.gcp;
      return { rewritten: replacement, findings: [] };
    }
  }

  // Unknown data source — warning
  const findings: TranslationFinding[] = [
    createFinding(
      'expression',
      'warning',
      'UNKNOWN_DATA_SOURCE',
      `No ${ctx.target} mapping for data source reference '${ref}'`,
    ),
  ];
  return { rewritten: ref, findings };
}

// ---------------------------------------------------------------------------
// Function call mapping
// ---------------------------------------------------------------------------

/**
 * Set of HCL built-in functions that pass through unchanged.
 * These are provider-agnostic Terraform/OpenTofu built-ins.
 */
const BUILTIN_FUNCTIONS: ReadonlySet<string> = new Set([
  'abs', 'ceil', 'floor', 'log', 'max', 'min', 'pow', 'signum',
  'chomp', 'format', 'formatlist', 'indent', 'join', 'lower', 'upper',
  'regex', 'regexall', 'replace', 'split', 'strrev', 'substr', 'title',
  'trim', 'trimprefix', 'trimsuffix', 'trimspace',
  'chunklist', 'coalesce', 'coalescelist', 'compact', 'concat',
  'contains', 'distinct', 'element', 'flatten', 'index', 'keys',
  'length', 'list', 'lookup', 'map', 'matchkeys', 'merge',
  'range', 'reverse', 'setintersection', 'setproduct', 'setsubtract',
  'setunion', 'slice', 'sort', 'transpose', 'values', 'zipmap',
  'base64decode', 'base64encode', 'base64gzip', 'csvdecode',
  'jsondecode', 'jsonencode', 'urlencode', 'yamldecode', 'yamlencode',
  'abspath', 'dirname', 'pathexpand', 'basename', 'file', 'fileexists',
  'fileset', 'filebase64', 'templatefile',
  'formatdate', 'timeadd', 'timestamp',
  'base64sha256', 'base64sha512', 'bcrypt', 'filebase64sha256',
  'filebase64sha512', 'filemd5', 'filesha1', 'filesha256', 'filesha512',
  'md5', 'rsadecrypt', 'sha1', 'sha256', 'sha512', 'uuid', 'uuidv5',
  'cidrhost', 'cidrnetmask', 'cidrsubnet', 'cidrsubnets',
  'can', 'try', 'tobool', 'tolist', 'tomap', 'tonumber', 'toset', 'tostring',
  'sensitive', 'nonsensitive', 'type',
]);

/**
 * Checks whether a function name is a known HCL built-in.
 *
 * @param funcName - The function name (e.g. "cidrsubnet")
 * @param args - The raw argument string (used in fallback rewrite for unknown functions)
 * @param ctx - Expression context (target provider used in finding messages)
 * @returns A TranslatedExpression with info finding for unknown functions, or null for builtins
 */
export function mapFunction(
  funcName: string,
  args: string,
  ctx: ExpressionContext,
): TranslatedExpression | null {
  if (BUILTIN_FUNCTIONS.has(funcName)) {
    // Known built-in — pass through, no rewriting needed
    return null;
  }

  // Unknown / provider-specific function — emit informational finding
  return {
    rewritten: `${funcName}(${args})`,
    findings: [
      createFinding(
        'expression',
        'info',
        'UNKNOWN_FUNCTION',
        `Function '${funcName}' is not a known HCL built-in; verify compatibility with ${ctx.target}`,
      ),
    ],
  };
}
